import{_ as s,o as n,c as e,ai as t}from"./chunks/framework.Ba-VnP44.js";const o=JSON.parse('{"title":"02 需求分析","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/02-lifecycle/requirement-analysis.md","filePath":"ai/productivity/dev-spec/02-lifecycle/requirement-analysis.md"}'),l={name:"ai/productivity/dev-spec/02-lifecycle/requirement-analysis.md"};function i(p,a,r,d,c,b){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="_02-需求分析" tabindex="-1">02 需求分析 <a class="header-anchor" href="#_02-需求分析" aria-label="Permalink to “02 需求分析”">​</a></h1><blockquote><p>第二层 · 开发生命周期。解决「如何用尽可能少的文字，把任务准确交给 AI」——沿用背景、目标、约束、输出格式四段式，补上任务分级、验收标准、阻塞问题处理。</p></blockquote><h2 id="什么时候用" tabindex="-1">什么时候用 <a class="header-anchor" href="#什么时候用" aria-label="Permalink to “什么时候用”">​</a></h2><p>任何开发任务开始前。简单任务一句话加必要限制就够；复杂任务才补业务背景、流程和验收条件。</p><p><strong>不是输入越详细越好，而是影响正确性的信息不能缺。</strong> 能从项目里查到的，不让用户重复写。</p><h2 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to “操作步骤”">​</a></h2><h3 id="任务输入结构" tabindex="-1">任务输入结构 <a class="header-anchor" href="#任务输入结构" aria-label="Permalink to “任务输入结构”">​</a></h3><table tabindex="0"><thead><tr><th>部分</th><th>要回答什么</th><th>是否必填</th></tr></thead><tbody><tr><td>背景</td><td>当前情况是什么</td><td>视任务而定</td></tr><tr><td>目标</td><td>具体要实现什么</td><td>必填</td></tr><tr><td>约束</td><td>哪些能改、哪些不能改</td><td>必填，至少说清关键边界</td></tr><tr><td>输出格式</td><td>最终交付什么</td><td>必填，默认输出执行结果</td></tr><tr><td>任务分级</td><td>需要多大程度的分析和验证</td><td>让 AI 先判断</td></tr><tr><td>验收标准</td><td>怎样才算完成</td><td>必填，简单任务可简写</td></tr></tbody></table><h3 id="任务分级" tabindex="-1">任务分级 <a class="header-anchor" href="#任务分级" aria-label="Permalink to “任务分级”">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>特征</th><th>执行方式</th></tr></thead><tbody><tr><td>L1 简单</td><td>范围明确、影响小</td><td>直接实施 + 局部检查</td></tr><tr><td>L2 普通</td><td>多文件、有业务逻辑</td><td>先分析影响 + 简要方案</td></tr><tr><td>L3 复杂</td><td>多模块、核心业务、数据结构、系统集成、高风险</td><td>完整分析 + 分阶段执行</td></tr></tbody></table><p>判断时看：修改范围、业务复杂度、数据影响、接口兼容性、回归风险、是否不可逆。<strong>改错了要回滚多个文件，就按 L3 走</strong>；改动一行代码但涉及订单状态、库存、资金，也可能是 L3。</p><h3 id="让-ai-主动发现缺失信息" tabindex="-1">让 AI 主动发现缺失信息 <a class="header-anchor" href="#让-ai-主动发现缺失信息" aria-label="Permalink to “让 AI 主动发现缺失信息”">​</a></h3><p>把信息分三类，不要让用户事先想全：</p><table tabindex="0"><thead><tr><th>类型</th><th>处理方式</th></tr></thead><tbody><tr><td>已确认</td><td>用户说明或代码资料能验证，直接采用</td></tr><tr><td>可推断</td><td>查证据后采用，不凭猜测</td></tr><tr><td>待确认</td><td>资料查不到且会影响结果，集中提问</td></tr></tbody></table><ul><li>能从项目里确认的，不问用户。</li><li>不影响正确性的细节，按项目现有规范处理。</li><li>涉及业务规则、数据一致性、权限、安全、不可逆操作的，不能猜。</li><li>所有阻塞问题一次性提出；没有阻塞就直接执行，不逐步问「要不要继续」。</li></ul><h3 id="明确验收标准" tabindex="-1">明确验收标准 <a class="header-anchor" href="#明确验收标准" aria-label="Permalink to “明确验收标准”">​</a></h3><p>验收标准要写成能核对的：功能行为、数据正确性、接口兼容性、测试要求。简单任务可简写成一句话，复杂任务逐条列。</p><p><strong>「完成开发」不算验收标准</strong>，要写成具体命令、diff 特征或页面行为。</p><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>最小任务输入（日常最常用）</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>任务：&lt;一句话说明要做什么&gt;</span></span>
<span class="line"><span>目标：&lt;预期结果&gt;</span></span>
<span class="line"><span>约束：&lt;允许改什么、不能改什么、必须保持兼容什么&gt;</span></span>
<span class="line"><span>验收：&lt;怎样算完成&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先检查项目现状，从代码和文档补全必要上下文，不要让我重复写能从项目里查到的信息。</span></span>
<span class="line"><span>把缺失信息分成「已确认 / 可推断 / 待确认」：能从项目确认的不问我；不影响正确性的细节按项目规范处理；涉及业务规则、数据一致性、权限、安全或不可逆操作的，不能猜。</span></span>
<span class="line"><span>所有真正阻塞的问题一次性提出；没有阻塞就直接分析并执行，不要每个小步骤都问我。</span></span>
<span class="line"><span>严格遵守修改范围，完成后执行必要的编译、测试和回归检查，给出修改内容、验证证据和遗留风险。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></details><details><summary><strong>复杂任务输入</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>【任务】本次要完成的具体事项。</span></span>
<span class="line"><span>【背景】当前业务情况、已有功能、为什么这次调整。</span></span>
<span class="line"><span>【目标】要实现的功能、要解决的问题、预期效果。</span></span>
<span class="line"><span>【约束】允许修改范围 / 不允许修改范围 / 必须保持兼容 / 技术或业务限制。</span></span>
<span class="line"><span>【验收标准】功能行为 / 数据正确性 / 接口兼容性 / 测试要求。</span></span>
<span class="line"><span>【交付要求】完成代码修改；执行必要的编译和测试；说明修改文件、实现结果和验证证据；汇总未解决问题和风险。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先分析任务，识别必要信息和潜在风险，再制定执行方案。</span></span>
<span class="line"><span>不要为了补充无关信息反复提问；不要自行编造项目里不存在的规则。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div></details><details><summary><strong>集中提问规则</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>在执行任务前，请先检查现有代码、项目文档和相关业务实现。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>缺失信息处理规则：</span></span>
<span class="line"><span>1. 能从现有项目确认的，不要问我。</span></span>
<span class="line"><span>2. 可以通过安全检查验证的，先自行检查。</span></span>
<span class="line"><span>3. 不影响业务正确性的细节，按项目现有规范处理。</span></span>
<span class="line"><span>4. 涉及业务规则、数据一致性、权限、安全、不可逆操作、兼容性的重要问题，不能自行猜测。</span></span>
<span class="line"><span>5. 把所有真正阻塞的问题集中整理，一次性提问。</span></span>
<span class="line"><span>6. 没有阻塞问题就直接制定方案并执行，不要逐步问我是否继续。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>非阻塞风险记录并说明处理依据，不要因此中断任务。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 需求已复述，模糊点已澄清或标注。</li><li>[ ] 至少写出了本次不做项和关键边界。</li><li>[ ] 验收标准可核对，不是「完成开发」。</li><li>[ ] 阻塞问题已集中提出并得到答案，或确认无阻塞。</li><li>[ ] 没有把推测写成已确认的业务规则。</li><li>[ ] 任务分级合理，简单任务没有被复杂化。</li></ul><p>需求阶段的产物是后续所有阶段的输入。这里含糊，后面全乱。下一步进入 <a href="/my-vitepress-site/ai/productivity/dev-spec/02-lifecycle/architecture-design.html">03 技术架构设计</a>。</p>`,25)])])}const u=s(l,[["render",i]]);export{o as __pageData,u as default};
